// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 skipBlocks) public {
        // keep the actor admissible
        vm.assume(actor != address(0) && actor != address(c));
        // settle shortly after the guessed block so its hash is still available (nonzero)
        skipBlocks = bound(skipBlocks, 2, 200);

        // a guess equal to keccak256(abi.encodePacked(bytes32(0))) — the value the
        // buggy version always compares against, since blockhash(current block) == 0
        bytes32 g = keccak256(abi.encodePacked(bytes32(0)));

        // actor locks in the guess with the required 1 ether
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // advance a few blocks: the guessed block's hash is still retrievable and nonzero
        vm.roll(block.number + skipBlocks);

        // settle; a revert must not mask the balance check
        vm.prank(actor);
        try c.settle() {} catch {}

        // General rule: c must never pay out unless the guess matches the hash of the
        // block locked at lockInGuess time. Here the guessed block's hash is nonzero,
        // so keccak256(abi.encodePacked(blockhash(guessedBlock))) != g and no payout
        // may occur: c must retain both 1-ether deposits.
        assertTrue(address(c).balance == 2 ether, "settle paid without matching the locked block hash");
    }
}
